import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface Message {
  id: string;
  text: string;
  type: 'success' | 'error';
}

@Injectable({ providedIn: 'root' })
export class MessageService {
  private messagesSubject = new BehaviorSubject<Message[]>([]);
  public messages$: Observable<Message[]> = this.messagesSubject.asObservable();
  private messageCounter = 0;

  addMessage(text: string, type: 'success' | 'error'): void {
    const id = `message-${this.messageCounter++}`;
    const message: Message = { id, text, type };
    const messages = this.messagesSubject.value;
    this.messagesSubject.next([...messages, message]);

    if (type === 'success') {
      setTimeout(() => this.removeMessage(id), 5000);
    }
  }

  removeMessage(id: string): void {
    const messages = this.messagesSubject.value;
    this.messagesSubject.next(messages.filter(m => m.id !== id));
  }
}
