import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ManufacturersService } from '../shared/services/manufacturers.service';
import { ManufacturerDto } from '../shared/dto/manufacturer.dto';
import { EditManufacturerComponent } from './edit-manufacturer/edit-manufacturer.component';
import { MessageService } from '../shared-widgets/messages/message.service';

@Component({
  selector: 'app-manufacturers',
  standalone: true,
  imports: [CommonModule, EditManufacturerComponent],
  templateUrl: './manufacturers.component.html',
  styleUrls: ['./manufacturers.component.css']
})
export class ManufacturersComponent implements OnInit {
  manufacturers: ManufacturerDto[] = [];
  showEditor = false;
  selectedManufacturer: ManufacturerDto | null = null;

  constructor(
    private manufacturersService: ManufacturersService,
    private messageService: MessageService
  ) {}

  ngOnInit(): void {
    this.loadManufacturers();
  }

  loadManufacturers(): void {
    this.manufacturersService.getManufacturers().subscribe({
      next: (manufacturers) => {
        this.manufacturers = manufacturers;
      },
      error: () => {
        this.messageService.addMessage('Error loading manufacturers', 'error');
      }
    });
  }

  onCreate(): void {
    this.selectedManufacturer = { name: '' };
    this.showEditor = true;
  }

  onEdit(manufacturer: ManufacturerDto): void {
    this.selectedManufacturer = { ...manufacturer };
    this.showEditor = true;
  }

  onDelete(manufacturer: ManufacturerDto): void {
    if (window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      this.manufacturersService.delete(manufacturer.id!).subscribe({
        next: () => {
          this.manufacturers = this.manufacturers.filter(m => m.id !== manufacturer.id);
          this.messageService.addMessage('Manufacturer deleted successfully', 'success');
        },
        error: () => {
          this.messageService.addMessage('Error deleting manufacturer', 'error');
        }
      });
    }
  }

  onSave(manufacturer: ManufacturerDto): void {
    this.manufacturersService.saveOrCreate(manufacturer).subscribe({
      next: (savedManufacturer) => {
        if (manufacturer.id) {
          const index = this.manufacturers.findIndex(m => m.id === manufacturer.id);
          if (index > -1) {
            this.manufacturers[index] = savedManufacturer;
          }
        } else {
          this.manufacturers.push(savedManufacturer);
        }
        this.showEditor = false;
        this.messageService.addMessage('Manufacturer saved successfully', 'success');
      },
      error: () => {
        this.messageService.addMessage('Error saving manufacturer', 'error');
      }
    });
  }

  onClose(): void {
    this.showEditor = false;
  }
}
```

