import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RatingsService } from '../shared/services/ratings.service';
import { CarsService } from '../shared/services/cars.service';
import { RatingDto } from '../shared/dto/rating.dto';
import { CarDto } from '../shared/dto/car.dto';
import { EditRatingComponent } from './edit-rating/edit-rating.component';
import { MessageService } from '../shared-widgets/messages/message.service';

@Component({
  selector: 'app-ratings',
  standalone: true,
  imports: [CommonModule, EditRatingComponent],
  templateUrl: './ratings.component.html',
  styleUrls: ['./ratings.component.css']
})
export class RatingsComponent implements OnInit {
  ratings: RatingDto[] = [];
  cars: CarDto[] = [];
  showEditor = false;

  constructor(
    private ratingsService: RatingsService,
    private carsService: CarsService,
    private messageService: MessageService
  ) {}

  ngOnInit(): void {
    this.loadRatings();
    this.loadCars();
  }

  loadRatings(): void {
    this.ratingsService.getRatings().subscribe({
      next: (ratings) => {
        this.ratings = ratings;
      },
      error: () => {
        this.messageService.addMessage('Error loading ratings', 'error');
      }
    });
  }

  loadCars(): void {
    this.carsService.getCars().subscribe({
      next: (cars) => {
        this.cars = cars;
      },
      error: () => {
        this.messageService.addMessage('Error loading cars', 'error');
      }
    });
  }

  onCreate(): void {
    this.showEditor = true;
  }

  onDelete(rating: RatingDto): void {
    if (window.confirm('Are you sure you want to delete this rating?')) {
      this.ratingsService.delete(rating.id!).subscribe({
        next: () => {
          this.ratings = this.ratings.filter(r => r.id !== rating.id);
          this.messageService.addMessage('Rating deleted successfully', 'success');
        },
        error: () => {
          this.messageService.addMessage('Error deleting rating', 'error');
        }
      });
    }
  }

  onSave(rating: RatingDto): void {
    this.ratingsService.saveOrCreate(rating).subscribe({
      next: (savedRating) => {
        this.ratings.push(savedRating);
        this.showEditor = false;
        this.messageService.addMessage('Rating saved successfully', 'success');
      },
      error: () => {
        this.messageService.addMessage('Error saving rating', 'error');
      }
    });
  }

  onClose(): void {
    this.showEditor = false;
  }

  getCarDisplayName(rating: RatingDto): string {
    if (rating.car && rating.car.manufacturer) {
      return rating.car.manufacturer.name + '/' + rating.car.model;
    }
    return '';
  }
}
