@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './edit-rating.component.html',
  styleUrls: ['./edit-rating.component.css']
})
export class EditRatingComponent implements OnInit {
  @Input() cars: CarDto[] = [];
  @Output() save = new EventEmitter<RatingDto>();
  @Output() close = new EventEmitter<void>();

  selectedCar: CarDto | null = null;
  rating: number | null = null;

  ngOnInit(): void {
    if (this.cars.length > 0) {
      this.selectedCar = this.cars[0];
    }
  }

  onSave(): void {
    if (this.selectedCar && this.rating) {
      const newRating: RatingDto = {
        car: this.selectedCar,
        rating: this.rating
      };
      this.save.emit(newRating);
    }
  }

  onClose(): void {
    this.close.emit();
  }

  getCarDisplayName(car: CarDto | null): string {
    if (car && car.manufacturer) {
      return car.manufacturer.name + '/' + car.model;
    }
    return '';
  }
}
